<?php
require 'includes/auth_helpers.php'; require 'includes/db.php'; require 'includes/toasts.php'; require_staff_or_admin($pdo);
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='add_category') {
    $name=trim((string)($_POST['category_name']??'')); $description=trim((string)($_POST['category_description']??'')); $parent=($_POST['parent_id']??'')===''?null:filter_var($_POST['parent_id'],FILTER_VALIDATE_INT);
    if (!csrf_check($_POST['csrf']??null)) $_SESSION['flash_error']='Session expired. Refresh and try again.';
    elseif ($name===''||mb_strlen($name)>100||mb_strlen($description)>500||($parent!==null&&(!$parent||(int)$parent<1))) $_SESSION['flash_error']='Enter a valid category name, description, and parent category.';
    else {
        if ($parent!==null) { $check=$pdo->prepare('SELECT parent_id FROM menu_categories WHERE category_id=?'); $check->execute([(int)$parent]); $parentRow=$check->fetch(); if (!$parentRow || $parentRow['parent_id']!==null) $_SESSION['flash_error']='Choose a top-level category as the parent. Subcategories cannot contain more subcategories.'; }
        if (empty($_SESSION['flash_error'])) { try { $sort=$pdo->prepare('SELECT COALESCE(MAX(sort_order),0)+1 FROM menu_categories WHERE parent_id <=> ?'); $sort->execute([$parent]); $pdo->prepare('INSERT INTO menu_categories (parent_id,name,description,sort_order) VALUES (?,?,?,?)')->execute([$parent,$name,$description?:null,(int)$sort->fetchColumn()]); $_SESSION['flash_success']='Menu category added.'; } catch (Throwable $e) { $_SESSION['flash_error']='Could not add the category. Please try again.'; } }
    }
    header('Location: menu-management.php'); exit;
}
$categories=$pdo->query('SELECT category_id,name,parent_id FROM menu_categories ORDER BY sort_order,name')->fetchAll();
$rootCategories=array_values(array_filter($categories,static fn($category)=>$category['parent_id']===null));
$items=$pdo->query('SELECT item_id,category_id,name,price,is_available,publish_at,item_kind,availability_scope,image_url,(image_data IS NOT NULL) AS has_image_data FROM menu_items ORDER BY name')->fetchAll();
$messages=[]; $success=$_SESSION['flash_success']??null; $error=$_SESSION['flash_error']??null; unset($_SESSION['flash_success'],$_SESSION['flash_error']); if ($success) $messages[]=['kind'=>'success','text'=>$success]; if ($error) $messages[]=['kind'=>'danger','text'=>$error];
$pageTitle='Menu management'; require 'includes/header.php'; render_toasts($messages);
?>
<main class="container py-5"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><p class="text-uppercase small fw-semibold text-secondary mb-1">Staff and admin</p><h1 class="mb-1">Menu management</h1><p class="text-secondary mb-0">Edit menu details, options, photos, and scheduled releases.</p></div><div class="d-flex gap-2"><button class="btn btn-outline-secondary" data-bs-toggle="modal" data-bs-target="#addCategoryModal"><i class="bi bi-folder-plus me-1"></i>Add category</button><a class="btn btn-auth" href="menu-item-edit.php"><i class="bi bi-plus-lg me-1"></i>Add menu entry</a></div></div>
<div class="mb-4"><button class="btn btn-outline-secondary" type="button" data-bs-toggle="collapse" data-bs-target="#existingCategories" aria-expanded="false" aria-controls="existingCategories"><i class="bi bi-folder2-open me-1"></i>Show existing categories (<?=count($categories)?>)</button><div class="collapse mt-3" id="existingCategories"><section class="card card-body"><h2 class="h5">Existing categories</h2><?php if (!$categories): ?><p class="text-secondary mb-0">No categories yet.</p><?php else: ?><ul class="list-group list-group-flush"><?php foreach ($categories as $category): ?><li class="list-group-item px-0 d-flex justify-content-between"><span><?=$category['parent_id']!==null?'↳ ':''?><?=e($category['name'])?></span><small class="text-secondary"><?=$category['parent_id']===null?'Top level':'Subcategory'?></small></li><?php endforeach; ?></ul><?php endif; ?></section></div></div>
<div class="row g-3 mb-4 align-items-end"><div class="col-md-3"><label class="form-label" for="menu-search">Search menu entries</label><input id="menu-search" class="form-control" type="search" placeholder="Search by name"></div><div class="col-sm-6 col-md-2"><label class="form-label" for="menu-category-filter">Category</label><select class="form-select" id="menu-category-filter"><option value="all">All categories</option><?php foreach($categories as $category): ?><option value="<?=(int)$category['category_id']?>"><?=$category['parent_id']!==null?'↳ ':''?><?=e($category['name'])?></option><?php endforeach; ?></select></div><div class="col-sm-6 col-md-2"><label class="form-label" for="menu-status-filter">Status</label><select class="form-select" id="menu-status-filter"><option value="all">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div><div class="col-sm-6 col-md-2"><label class="form-label" for="menu-type-filter">Entry type</label><select class="form-select" id="menu-type-filter"><option value="all">All types</option><option value="item">Menu item</option><option value="option">Option</option></select></div><div class="col-sm-6 col-md-1"><label class="form-label" for="menu-sort-by">Sort</label><select class="form-select" id="menu-sort-by"><option value="name">Name</option><option value="price">Price</option><option value="status">Status</option><option value="type">Type</option></select></div><div class="col-sm-6 col-md-2"><label class="form-label" for="menu-sort-direction">Order</label><select class="form-select" id="menu-sort-direction"><option value="asc">Ascending</option><option value="desc">Descending</option></select></div></div>
<div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-4" id="menu-admin-grid">
<?php foreach ($items as $item): $available=(int)$item['is_available']===1; $release=$item['publish_at']?new DateTimeImmutable((string)$item['publish_at'],new DateTimeZone('Asia/Manila')):null; $future=$release&&$release>new DateTimeImmutable('now',new DateTimeZone('Asia/Manila')); $image=$item['has_image_data']?'menu-image.php?id='.(int)$item['item_id']:(string)$item['image_url']; ?>
<div class="col menu-admin-card-wrap" data-name="<?=e(mb_strtolower($item['name']))?>" data-category="<?=(int)$item['category_id']?>" data-price="<?=e((string)($item['price']??-1))?>" data-status="<?=$available?'active':'inactive'?>" data-type="<?=e($item['item_kind'])?>"><a class="menu-admin-card-link" href="menu-item-edit.php?id=<?=(int)$item['item_id']?>" aria-label="Edit <?=e($item['name'])?>"><article class="menu-admin-card h-100"><img class="menu-admin-photo" src="<?=e($image?:'assets/menu-placeholder.svg')?>" alt="<?=e($item['name'])?>" loading="lazy"><div class="p-3"><div class="d-flex justify-content-between align-items-start gap-2"><h2 class="h5 mb-2"><?=e($item['name'])?></h2><span class="badge <?=$item['item_kind']==='option'?'text-bg-info':'text-bg-secondary'?>"><?=e(ucfirst($item['item_kind']))?></span></div><p class="mb-2 fw-semibold"><?=$item['price']===null?'Option only':'₱'.number_format((float)$item['price'],2)?></p><p class="small text-secondary mb-2">Available as: <?=e(str_replace('_',' ',$item['availability_scope']))?></p><p class="small mb-0 <?=$available?'text-success':'text-danger'?>"><?=$available?'Active':'Inactive'?><?php if($release): ?> · <?=e($release->format('M j, Y g:i A'))?><?=$future?' (scheduled)':''?><?php else: ?> · Immediate release<?php endif; ?></p><span class="small text-secondary d-block mt-3"><i class="bi bi-pencil-square me-1"></i>Select to edit</span></div></article></a></div>
<?php endforeach; ?></div><p id="menu-empty" class="text-secondary" hidden>No entries match your search.</p></main>
<div class="modal fade" id="addCategoryModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><div class="modal-header"><h2 class="modal-title fs-5">Add menu category</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_category"><label class="form-label" for="category-name">Category name</label><input class="form-control mb-3" id="category-name" name="category_name" maxlength="100" required><label class="form-label" for="category-description">Description (optional)</label><textarea class="form-control mb-3" id="category-description" name="category_description" maxlength="500" rows="2"></textarea><label class="form-label" for="category-parent">Parent category (optional)</label><select class="form-select" id="category-parent" name="parent_id"><option value="">Top-level category</option><?php foreach($rootCategories as $category): ?><option value="<?=(int)$category['category_id']?>"><?=e($category['name'])?></option><?php endforeach; ?></select><div class="form-text">Categories can have one level of subcategories.</div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-auth" type="submit">Confirm and add</button></div></form></div></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const grid=document.getElementById('menu-admin-grid'),cards=[...grid.querySelectorAll('.menu-admin-card-wrap')],empty=document.getElementById('menu-empty'),controls=['menu-search','menu-category-filter','menu-status-filter','menu-type-filter','menu-sort-by','menu-sort-direction'].map(id=>document.getElementById(id));const [search,category,status,type,sort,direction]=controls;function update(){const q=search.value.trim().toLowerCase();cards.forEach(card=>card.hidden=!(card.dataset.name.includes(q)&&(category.value==='all'||card.dataset.category===category.value)&&(status.value==='all'||card.dataset.status===status.value)&&(type.value==='all'||card.dataset.type===type.value)));const visible=cards.filter(card=>!card.hidden);visible.sort((a,b)=>{let av=a.dataset[sort.value],bv=b.dataset[sort.value];let cmp=sort.value==='price'?Number(av)-Number(bv):av.localeCompare(bv,undefined,{numeric:true,sensitivity:'base'});return direction.value==='desc'?-cmp:cmp;});visible.forEach(card=>grid.appendChild(card));empty.hidden=visible.length>0;}controls.forEach(control=>control.addEventListener(control===search?'input':'change',update));update();});</script>
<?php require 'includes/footer.php'; ?>
